INSERT OR REPLACE INTO languages (code, name_vi, native_name, script_system, levels_json, font_family, description, is_active) VALUES ('zh', 'Tiếng Trung', '中文 (普通话)', 'Chữ Hán giản thể & Phiên âm Pinyin (汉字 / 拼音)', '["HSK 1", "HSK 2", "HSK 3", "HSK 4", "HSK 5", "HSK 6"]', '''Noto Sans SC'', ''PingFang SC'', ''Microsoft YaHei'', sans-serif', 'Thực hành Tiếng Trung giao tiếp và học thuật theo chuẩn HSK với hệ thống chữ Hán, thanh điệu Pinyin và cấu trúc câu đặc thù.', 1);
INSERT OR REPLACE INTO languages (code, name_vi, native_name, script_system, levels_json, font_family, description, is_active) VALUES ('en', 'Tiếng Anh', 'English', 'Bảng chữ cái Latin & Phiên âm quốc tế IPA', '["A1", "A2", "B1", "B2", "C1", "C2"]', '''Be Vietnam Pro'', ''Inter'', ''Segoe UI'', sans-serif', 'Thực hành Tiếng Anh toàn cầu theo khung tham chiếu CEFR (A1–C2) phục vụ học tập, giao tiếp đời sống và công việc.', 1);
INSERT OR REPLACE INTO languages (code, name_vi, native_name, script_system, levels_json, font_family, description, is_active) VALUES ('ko', 'Tiếng Hàn', '한국어 (Hangul)', 'Bảng chữ cái Hangeul (한글) & Quy tắc biến âm', '["TOPIK I - Cấp 1", "TOPIK I - Cấp 2", "TOPIK II - Cấp 3", "TOPIK II - Cấp 4", "TOPIK II - Cấp 5", "TOPIK II - Cấp 6"]', '''Noto Sans KR'', ''Malgun Gothic'', sans-serif', 'Thực hành Tiếng Hàn theo chuẩn TOPIK với cấu trúc câu Chủ - Tân - Động (S-O-V), tiểu từ và kính ngữ.', 1);
INSERT OR REPLACE INTO languages (code, name_vi, native_name, script_system, levels_json, font_family, description, is_active) VALUES ('ja', 'Tiếng Nhật', '日本語', 'Hệ chữ Hiragana, Katakana, Kanji & Romaji (ひらがな・カタカナ・漢字)', '["JLPT N5", "JLPT N4", "JLPT N3", "JLPT N2", "JLPT N1"]', '''Noto Sans JP'', ''Hiragino Kaku Gothic Pro'', ''Meiryo'', sans-serif', 'Thực hành Tiếng Nhật theo lộ trình JLPT N5–N1 kết hợp bảng chữ mềm Hiragana, chữ cứng Katakana và Hán tự Kanji.', 1);
INSERT OR REPLACE INTO languages (code, name_vi, native_name, script_system, levels_json, font_family, description, is_active) VALUES ('ru', 'Tiếng Nga', 'Русский язык', 'Bảng chữ cái Kirin (Кириллица) & Hệ thống 6 cách ngữ pháp', '["TRKI A1", "TRKI A2", "TRKI B1", "TRKI B2", "TRKI C1"]', '''Noto Sans'', ''PT Sans'', ''Segoe UI'', sans-serif', 'Thực hành Tiếng Nga với bảng chữ cái Kirin, trọng âm từ vựng và 6 cách biến đổi danh từ/tính từ trong ngữ cảnh thực tế.', 1);
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_zh_listen_1', 'zh', 'listening', 'HSK 1', 'Chào hỏi & Làm quen', 'Nghe điền từ Tiếng Trung: Lời chào buổi sáng', 'Nghe phát âm câu hội thoại Tiếng Trung (hoặc đọc phiên âm hỗ trợ) và điền từ chữ Hán còn thiếu vào chỗ trống.', '{"audio_text": "你好，请问你叫什么名字？", "transcript_masked": "你好，请问你叫___名字？", "pinyin": "Nǐ hǎo, qǐngwèn nǐ jiào ___ míngzi?", "speed_options": [0.75, 1.0, 1.25], "hints": ["Từ để hỏi ''cái gì'' trong Tiếng Trung (2 chữ Hán)"]}', '{"blanks": ["什么"], "acceptable": ["什么", "shénme"]}', 'Trong Tiếng Trung, ''什么'' (shénme) nghĩa là ''cái gì'', đứng trước danh từ ''名字'' (míngzi - tên) để hỏi ''tên là gì''.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_zh_vocab_1', 'zh', 'vocabulary', 'HSK 1', 'Đời sống học đường', 'Bộ thẻ Từ vựng Tiếng Trung HSK 1 cốt lõi', 'Lật thẻ Flashcard để ôn tập chữ Hán, phiên âm Pinyin, nghĩa Tiếng Việt và hoàn thành câu hỏi kiểm tra trí nhớ.', '{"cards": [{"term": "学习", "pronunciation": "xuéxí", "meaning_vi": "Học tập, rèn luyện", "example": "我们一起学习汉语。 (Chúng tôi cùng nhau học Tiếng Trung.)"}, {"term": "朋友", "pronunciation": "péngyou", "meaning_vi": "Người bạn, bạn bè", "example": "他是我的好朋友。 (Anh ấy là bạn tốt của tôi.)"}, {"term": "图书馆", "pronunciation": "túshūguǎn", "meaning_vi": "Thư viện", "example": "我在图书馆看书。 (Tôi đọc sách ở thư viện.)"}], "quiz_question": "Từ nào trong Tiếng Trung có nghĩa là ''Thư viện''?", "quiz_options": ["学习", "朋友", "图书馆", "学校"]}', '{"correct_option": "图书馆"}', '''图书馆'' (túshūguǎn) nghĩa là Thư viện; ''学习'' là học tập và ''朋友'' là bạn bè.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_zh_sent_1', 'zh', 'sentence', 'HSK 2', 'Kế hoạch hàng ngày', 'Sắp xếp câu Tiếng Trung chuẩn cấu trúc Thời gian - Địa điểm - Hành động', 'Kéo thả hoặc bấm chọn các từ bị xáo trộn để ghép thành câu Tiếng Trung hoàn chỉnh.', '{"shuffled_tokens": ["看书", "我", "在图书馆", "今天下午"], "translation_vi": "Chiều hôm nay tôi đọc sách ở thư viện."}', '{"ordered_tokens": ["今天下午", "我", "在图书馆", "看书"], "Alt_ordered": ["我", "今天下午", "在图书馆", "看书"]}', 'Quy tắc trật tự từ Tiếng Trung: Chủ ngữ + Trạng ngữ chỉ thời gian (hoặc Thời gian + Chủ ngữ) + 在 (ở) + Địa điểm + Động từ + Tân ngữ.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_zh_read_1', 'zh', 'reading', 'HSK 2', 'Giao lưu câu lạc bộ', 'Đọc hiểu Tiếng Trung: Buổi sinh hoạt ngoại ngữ cuối tuần', 'Đọc đoạn văn chữ Hán bên dưới và chọn đáp án đúng cho câu hỏi.', '{"passage": "每个星期六上午，林明都会去学校的外语俱乐部练习口语。在那里，他认识了很多喜欢中文和英语的朋友。他们一起讨论学习方法，互相帮助。", "pinyin_support": "Měi gè xīngqīliù shàngwǔ, Lín Míng dōu huì qù xuéxiào de wàiyǔ jùlèbù liànxí kǒuyǔ...", "questions": [{"q": "林明每个星期六上午去哪里？ (Sáng thứ Bảy hàng tuần Lâm Minh đi đâu?)", "options": ["去学校的外语俱乐部", "去电影院", "去超市", "在家休息"]}]}', '{"answers": ["去学校的外语俱乐部"]}', 'Đoạn văn nêu rõ: ''每个星期六上午，林明都会去学校的外语俱乐部练习口语'' (Mỗi sáng thứ Bảy, Lâm Minh đều đến câu lạc bộ ngoại ngữ của trường để luyện nói).', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_en_listen_1', 'en', 'listening', 'A2', 'Daily Practice', 'Nghe điền từ Tiếng Anh: Thói quen rèn luyện phản xạ', 'Nghe câu Tiếng Anh và điền từ còn thiếu vào chỗ trống.', '{"audio_text": "Consistent daily practice is the bridge between learning vocabulary and speaking fluently.", "transcript_masked": "Consistent daily ___ is the bridge between learning vocabulary and speaking fluently.", "ipa": "/kənˈsɪstənt ˈdeɪli ˈpræktɪs/", "speed_options": [0.75, 1.0, 1.25], "hints": ["Danh từ mang nghĩa ''sự thực hành / luyện tập'' (8 chữ cái)"]}', '{"blanks": ["practice"], "acceptable": ["practice"]}', 'Cụm danh từ ''Consistent daily practice'' nghĩa là ''Việc thực hành đều đặn hàng ngày''.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_en_vocab_1', 'en', 'vocabulary', 'B1', 'Community & Collaboration', 'Từ vựng Tiếng Anh: Giao tiếp & Kết nối cộng đồng', 'Xem giải nghĩa, phiên âm IPA, lật thẻ Flashcard và trả lời câu hỏi kiểm tra trí nhớ.', '{"cards": [{"term": "collaborate", "pronunciation": "/kəˈlæbəreɪt/", "meaning_vi": "Hợp tác, cộng tác cùng nhau", "example": "Members collaborate on weekly language challenges."}, {"term": "fluency", "pronunciation": "/ˈfluːənsi/", "meaning_vi": "Sự trôi chảy, lưu loát", "example": "Regular conversation builds natural fluency."}, {"term": "context", "pronunciation": "/ˈkɒntekst/", "meaning_vi": "Ngữ cảnh, bối cảnh", "example": "Always learn new words in a clear context."}], "quiz_question": "Từ nào mang nghĩa ''Ngữ cảnh, bối cảnh'' trong Tiếng Anh?", "quiz_options": ["context", "fluency", "collaborate", "accent"]}', '{"correct_option": "context"}', '''context'' (/ˈkɒntekst/) là ngữ cảnh; việc học từ trong ngữ cảnh giúp ghi nhớ sâu hơn học thuộc lòng.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_en_sent_1', 'en', 'sentence', 'A2', 'Finding a Study Partner', 'Sắp xếp câu Tiếng Anh: Kết nối bạn cùng mục tiêu', 'Sắp xếp các từ bị xáo trộn để tạo thành câu Tiếng Anh đúng ngữ pháp.', '{"shuffled_tokens": ["together", "practice", "to", "every evening", "We", "meet"], "translation_vi": "Chúng tôi gặp nhau để cùng luyện tập vào mỗi buổi tối."}', '{"ordered_tokens": ["We", "meet", "to", "practice", "together", "every evening"], "Alt_ordered": ["every evening", "We", "meet", "to", "practice", "together"]}', 'Cấu trúc ''We meet to practice together every evening'' sử dụng động từ nguyên mẫu có ''to'' (to practice) để chỉ mục đích.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_en_read_1', 'en', 'reading', 'B1', 'Active Language Learning', 'Đọc hiểu Tiếng Anh: Vượt qua rào cản tự học ngoại ngữ', 'Đọc đoạn văn ngắn và chọn câu trả lời đúng nhất.', '{"passage": "Many learners memorize long lists of grammar rules on paper but struggle to respond in real conversations. When learners combine short listening exercises, sentence building, and peer practice in a supportive community, they retain knowledge much longer.", "questions": [{"q": "Theo đoạn văn, điều gì giúp người học ghi nhớ kiến thức lâu hơn?", "options": ["Kết hợp bài nghe ngắn, sắp xếp câu và thực hành cùng bạn học trong cộng đồng", "Chỉ học thuộc lòng danh sách quy tắc ngữ pháp trên giấy", "Tránh giao tiếp thực tế", "Chỉ xem video thụ động mà không thực hành"]}]}', '{"answers": ["Kết hợp bài nghe ngắn, sắp xếp câu và thực hành cùng bạn học trong cộng đồng"]}', 'Đoạn văn chỉ rõ việc kết hợp bài tập thực hành ngắn (listening, sentence building) với thực hành cùng bạn học (peer practice) giúp duy trì kiến thức lâu dài.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ko_listen_1', 'ko', 'listening', 'TOPIK I - Cấp 1', 'Giới thiệu bản thân', 'Nghe điền từ Tiếng Hàn: Chào hỏi lần đầu', 'Nghe câu Tiếng Hàn và điền từ Hangeul còn thiếu vào chỗ trống.', '{"audio_text": "안녕하세요, 만나서 반갑습니다.", "transcript_masked": "안녕하세요, 만나서 ___.", "romaji": "Annyeonghaseyo, mannaseo bangapseumnida.", "speed_options": [0.75, 1.0, 1.25], "hints": ["Biểu hiện lịch sự mang nghĩa ''rất vui được gặp bạn'' (6 âm tiết Hangeul)"]}', '{"blanks": ["반갑습니다"], "acceptable": ["반갑습니다"]}', '''만나서 반갑습니다'' (mannaseo bangapseumnida) là câu chào lịch sự chuẩn mực trong Tiếng Hàn nghĩa là ''Rất hân hạnh được gặp bạn''.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ko_vocab_1', 'ko', 'vocabulary', 'TOPIK I - Cấp 2', 'Sinh hoạt hàng ngày', 'Bộ từ vựng Tiếng Hàn sơ cấp cốt lõi', 'Ôn tập thẻ từ Hangeul và trả lời câu hỏi kiểm tra trí nhớ.', '{"cards": [{"term": "연습하다", "pronunciation": "yeon-seup-ha-da", "meaning_vi": "Luyện tập, thực hành", "example": "매일 한국어를 연습해요. (Mỗi ngày tôi đều luyện tập Tiếng Hàn.)"}, {"term": "동아리", "pronunciation": "dong-a-ri", "meaning_vi": "Câu lạc bộ", "example": "우리 학교 외국어 동아리에 가입했어요. (Tôi đã tham gia CLB ngoại ngữ của trường.)"}, {"term": "도서관", "pronunciation": "do-seo-gwan", "meaning_vi": "Thư viện", "example": "도서관에서 책을 읽어요. (Tôi đọc sách ở thư viện.)"}], "quiz_question": "Từ Tiếng Hàn nào có nghĩa là ''Câu lạc bộ''?", "quiz_options": ["동아리", "도서관", "연습하다", "학교"]}', '{"correct_option": "동아리"}', '''동아리'' (dong-a-ri) là Câu lạc bộ (đặc biệt phổ biến trong trường học và sinh viên Hàn Quốc).', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ko_sent_1', 'ko', 'sentence', 'TOPIK I - Cấp 2', 'Cấu trúc S-O-V', 'Sắp xếp câu Tiếng Hàn chuẩn trật tự Chủ ngữ - Tân ngữ - Động từ', 'Ghép các thành phần sau thành câu Tiếng Hàn đúng ngữ pháp.', '{"shuffled_tokens": ["배워요", "한국어를", "저는", "친구와 함께"], "translation_vi": "Tôi học Tiếng Hàn cùng với bạn."}', '{"ordered_tokens": ["저는", "친구와 함께", "한국어를", "배워요"], "Alt_ordered": ["친구와 함께", "저는", "한국어를", "배워요"]}', 'Tiếng Hàn tuân theo cấu trúc S-O-V: Chủ ngữ (저는) + Cụm trạng ngữ (친구와 함께) + Tân ngữ (한국어를) + Động từ ở cuối câu (배워요).', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ko_read_1', 'ko', 'reading', 'TOPIK I - Cấp 2', 'Lịch trình học tập', 'Đọc hiểu Tiếng Hàn: Thói quen ôn từ vựng buổi tối', 'Đọc đoạn văn Tiếng Hàn và chọn câu trả lời đúng.', '{"passage": "민수 씨는 매일 저녁 여덟 시에 외국어 단어를 복습합니다. 그리고 주말에는 동아리 친구들과 같이 한국어로 이야기합니다.", "questions": [{"q": "민수 씨는 매일 저녁에 무엇을 합니까? (Mỗi tối Minsu làm gì?)", "options": ["외국어 단어를 복습합니다 (Ôn tập từ vựng ngoại ngữ)", "영화를 봅니다 (Xem phim)", "운동을 합니다 (Tập thể dục)", "요리를 합니다 (Nấu ăn)"]}]}', '{"answers": ["외국어 단어를 복습합니다 (Ôn tập từ vựng ngoại ngữ)"]}', 'Câu đầu tiên nêu rõ: ''민수 씨는 매일 저녁 여덟 시에 외국어 단어를 복습합니다'' (Minsu ôn tập từ vựng ngoại ngữ vào 8 giờ tối mỗi ngày).', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ja_listen_1', 'ja', 'listening', 'JLPT N5', 'Hội thoại cơ bản', 'Nghe điền từ Tiếng Nhật: Xin giúp đỡ lịch sự', 'Nghe câu Tiếng Nhật và điền từ Hiragana còn thiếu vào chỗ trống.', '{"audio_text": "これからどうぞよろしくお願いします。", "transcript_masked": "これからどうぞよろしく___。", "romaji": "Korekara douzo yoroshiku onegaishimasu.", "speed_options": [0.75, 1.0, 1.25], "hints": ["Cụm kết câu lịch sự ''onegaishimasu'' bằng Hiragana"]}', '{"blanks": ["おねがいします"], "acceptable": ["おねがいします", "お願いします"]}', '''どうぞよろしくお願いします'' (Douzo yoroshiku onegaishimasu) là lời chào mở đầu mối quan hệ hợp tác/kết bạn rất quan trọng trong Tiếng Nhật.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ja_vocab_1', 'ja', 'vocabulary', 'JLPT N5', 'Học tập & Đời sống', 'Từ vựng Tiếng Nhật N5: Chữ Kanji & Hiragana cơ bản', 'Lật thẻ Flashcard để ghi nhớ Kanji, cách đọc Hiragana và nghĩa Tiếng Việt.', '{"cards": [{"term": "練習 (れんしゅう)", "pronunciation": "renshū", "meaning_vi": "Sự luyện tập, thực hành", "example": "毎日、日本語の会話を練習します。"}, {"term": "言葉 (ことば)", "pronunciation": "kotoba", "meaning_vi": "Từ ngữ, ngôn ngữ", "example": "新しい言葉を覚えます。"}, {"term": "仲間 (なかま)", "pronunciation": "nakama", "meaning_vi": "Bạn đồng hành, đồng đội", "example": "一緒に学ぶ仲間を見つけましょう。"}], "quiz_question": "Từ nào trong Tiếng Nhật đọc là ''renshū'' và có nghĩa là ''Luyện tập''?", "quiz_options": ["練習 (れんしゅう)", "言葉 (ことば)", "仲間 (なかま)", "先生 (せんせい)"]}', '{"correct_option": "練習 (れんしゅう)"}', '''練習'' (れんしゅう - renshū) có nghĩa là luyện tập/thực hành.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ja_sent_1', 'ja', 'sentence', 'JLPT N5', 'Trợ từ Tiếng Nhật', 'Sắp xếp câu Tiếng Nhật với trợ từ で và を', 'Sắp xếp các từ để tạo thành câu Tiếng Nhật hoàn chỉnh.', '{"shuffled_tokens": ["勉強します", "日本語を", "図書館で", "私は"], "translation_vi": "Tôi học Tiếng Nhật ở thư viện."}', '{"ordered_tokens": ["私は", "図書館で", "日本語を", "勉強します"], "Alt_ordered": ["図書館で", "私は", "日本語を", "勉強します"]}', 'Trợ từ ''で'' chỉ nơi diễn ra hành động (図書館で - ở thư viện), trợ từ ''を'' chỉ tân ngữ trực tiếp (日本語を) đứng trước động từ ''勉強します''.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ja_read_1', 'ja', 'reading', 'JLPT N5', 'Thực hành mỗi ngày', 'Đọc hiểu Tiếng Nhật: Buổi đọc sách buổi sáng', 'Đọc đoạn văn Tiếng Nhật và chọn đáp án đúng.', '{"passage": "さくらさんは毎朝七時に起きます。朝ごはんの後で、三十分ぐらい日本語の短い文章を読みます。分からない言葉がある時は、辞書で調べます。", "questions": [{"q": "さくらさんは朝ごはんの後で何をしますか？ (Sau bữa sáng Sakura làm gì?)", "options": ["日本語の短い文章を読みます (Đọc đoạn văn ngắn Tiếng Nhật)", "テレビを見ます (Xem TV)", "買い物に行きます (Đi mua sắm)", "寝ます (Đi ngủ)"]}]}', '{"answers": ["日本語の短い文章を読みます (Đọc đoạn văn ngắn Tiếng Nhật)"]}', 'Đoạn văn nêu rõ: ''朝ごはんの後で、三十分ぐらい日本語の短い文章を読みます'' (Sau bữa sáng, đọc đoạn văn ngắn Tiếng Nhật khoảng 30 phút).', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ru_listen_1', 'ru', 'listening', 'TRKI A1', 'Giao tiếp cơ bản', 'Nghe điền từ Tiếng Nga: Lời chào và làm quen', 'Nghe câu Tiếng Nga và điền từ chữ Kirin còn thiếu vào chỗ trống.', '{"audio_text": "Здравствуйте, мы изучаем русский язык вместе.", "transcript_masked": "Здравствуйте, мы изучаем ___ язык вместе.", "translit": "Zdravstvuyte, my izuchayem russkiy yazyk vmeste.", "speed_options": [0.75, 1.0, 1.25], "hints": ["Tính từ ''thuộc về Tiếng Nga'' (7 chữ cái Kirin)"]}', '{"blanks": ["русский"], "acceptable": ["русский", "Русский"]}', '''русский язык'' (russkiy yazyk) nghĩa là Tiếng Nga; ''мы изучаем русский язык вместе'' là ''Chúng tôi cùng nhau học Tiếng Nga''.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ru_vocab_1', 'ru', 'vocabulary', 'TRKI A1', 'Học thuật & Bạn bè', 'Bộ từ vựng Tiếng Nga chữ Kirin nền tảng', 'Ôn tập từ vựng Tiếng Nga có đánh dấu trọng âm và trả lời câu hỏi.', '{"cards": [{"term": "пра́ктика", "pronunciation": "práktika", "meaning_vi": "Sự thực hành, rèn luyện", "example": "Ежедневная практика очень важна."}, {"term": "слова́рь", "pronunciation": "slovár''", "meaning_vi": "Từ điển, bộ từ vựng", "example": "Это мой новый русско-вьетнамский словарь."}, {"term": "соо́бщество", "pronunciation": "soóbshchestvo", "meaning_vi": "Cộng đồng", "example": "Наше языковое сообщество открыто для всех."}], "quiz_question": "Từ Tiếng Nga nào mang nghĩa là ''Cộng đồng''?", "quiz_options": ["соо́бщество", "пра́ктика", "слова́рь", "учи́тель"]}', '{"correct_option": "соо́бщество"}', '''соо́бщество'' (soóbshchestvo) là Cộng đồng; ''пра́ктика'' là thực hành và ''слова́рь'' là từ điển/bộ từ vựng.', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ru_sent_1', 'ru', 'sentence', 'TRKI A1', 'Cấu trúc câu Tiếng Nga', 'Sắp xếp câu Tiếng Nga: Thực hành hội thoại cùng bạn bè', 'Ghép các từ chữ Kirin thành câu Tiếng Nga hoàn chỉnh.', '{"shuffled_tokens": ["каждый день", "практикуем", "Мы", "разговорную речь"], "translation_vi": "Chúng tôi thực hành ngôn ngữ nói mỗi ngày."}', '{"ordered_tokens": ["Мы", "практикуем", "разговорную речь", "каждый день"], "Alt_ordered": ["каждый день", "Мы", "практикуем", "разговорную речь"]}', 'Câu hoàn chỉnh: ''Мы практикуем разговорную речь каждый день'' (Chúng tôi thực hành hội thoại/ngôn ngữ nói mỗi ngày).', 10, '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO practice_exercises (id, language_code, tool_type, level, topic, title, instructions, content_json, answer_json, explanation, points, created_at) VALUES ('ex_ru_read_1', 'ru', 'reading', 'TRKI A2', 'Câu lạc bộ ngôn ngữ', 'Đọc hiểu Tiếng Nga: Không gian trao đổi đa ngôn ngữ', 'Đọc đoạn văn Tiếng Nga và chọn đáp án đúng.', '{"passage": "В нашем студенческом клубе ребята читают статьи на русском и английском языках, обсуждают новые слова и помогают друг другу исправлять ошибки.", "questions": [{"q": "Что делают ребята в студенческом клубе? (Các bạn trong câu lạc bộ sinh viên làm gì?)", "options": ["Читают статьи, обсуждают новые слова и помогают друг другу", "Только смотрят фильмы без обсуждения", "Изучают только математику", "Играют в футбол"]}]}', '{"answers": ["Читают статьи, обсуждают новые слова и помогают друг другу"]}', 'Đoạn văn nêu rõ các thành viên đọc bài viết bằng Tiếng Nga và Tiếng Anh, thảo luận từ mới và giúp nhau sửa lỗi.', 10, '2026-11-15T00:00:00.000Z');
